    /**
     * החזרת SVG מוטמע עבור אייקון לפי שם סמנטי.
     *
     * @param string $name שם האייקון (מפתח במפה).
     * @param array  $args {
     *     @type string $class מחלקות CSS נוספות מעבר ל-uc-ic.
     *     @type string $label טקסט aria-label; אם קיים — האייקון מקבל role="img" ונקרא ע"י קורא-מסך.
     *                         אם ריק — האייקון מוגדר aria-hidden (מתאים לתוך כפתור עם title/aria-label משלו).
     * }
     * @return string
     */
    public static function svg($name, $args = []) {
        $inner = isset(self::$paths[$name]) ? self::$paths[$name] : null;
        if ($inner === null) {
            return ''; // אייקון לא מוכר — לא פולטים כלום (fail-safe)
        }
        $classes = 'uc-ic uc-ic-' . $name;
        if (!empty($args['class'])) {
            $classes .= ' ' . $args['class'];
        }
        $a11y = ' aria-hidden="true"';
        if (!empty($args['label'])) {
            $a11y = ' role="img" aria-label="' . esc_attr($args['label']) . '"';
        }
        return '<svg class="' . esc_attr($classes) . '" viewBox="0 0 256 256" fill="currentColor"'
             . $a11y . ' focusable="false">' . $inner . '</svg>';
    }

    /**
     * בדיקה אם קיים אייקון בשם נתון.
     * @param string $name
     * @return bool
     */
    public static function has($name) {
        return isset(self::$paths[$name]);
    }

    /**
     * מחזיר קטע JavaScript שמגדיר window.UC_ICON(name) — אותו מקור-אמת של האייקונים,
     * לשימוש בהחלפות דינמיות ב-JS (למשל ▶️↔⏸️, 🎸↔🎹). מוזרק inline לפני main.js
     * כדי להבטיח זמינות ללא תלות בסדר-טעינה או ברשת.
     *
     * שימוש ב-JS:  el.innerHTML = UC_ICON('pause');
     * @return string
     */
    public static function js_snippet() {
        $map = wp_json_encode(self::$paths);
        return 'window.UC_ICON=function(n){var p=' . $map
             . ';return p[n]?(\'<svg class="uc-ic uc-ic-\'+n+\'" viewBox="0 0 256 256" fill="currentColor" aria-hidden="true" focusable="false">\'+p[n]+\'</svg>\'):\'\';};';
    }
}

/**
 * מעטפת גלובלית נוחה — זמינה בכל מקום (תוסף + ערכת-בת).
 * @param string $name
 * @param array  $args
 * @return string
 */
if (!function_exists('ams_icon')) {
    function ams_icon($name, $args = []) {
        return AMS_Icons::svg($name, $args);
    }
}
